def is_valid_original(derived):
    n = len(derived)
    if n == 1:
        return derived[0] == 0  # original must be [0] if derived is [0], else can't form valid original

    # The original values can be constructed from derived
    # Let's assume original[0] is some value x (0 or 1), then we can derive others
    original = [0] * n

    # Calculate the first value of original as 0 (it could be 0 or 1, but we can start with 0)
    original[0] = 0

    for i in range(n - 1):
        original[i + 1] = derived[i] ^ original[i]

    # Now to find original[n-1], we calculate what it should be
    original[n - 1] = derived[n - 1] ^ original[0]

    # Finally, check if derived is consistent with the original array we've built
    for i in range(n):
        if i == n - 1:
            if (original[i] ^ original[0]) != derived[i]:
                return False
        else:
            if (original[i] ^ original[i + 1]) != derived[i]:
                return False

    return True
