def fill_polyominoes():
    import sys
    from collections import deque

    input = sys.stdin.read
    grid_str = input().strip().split()

    assert len(grid_str) == 12
    polyominoes = []

    for i in range(3):
        polyomino = [grid_str[4 * i + j] for j in range(4)]
        polyominoes.append(polyomino)

    def rotate(poly):
        return [''.join(poly[3-j][i] for j in range(4)) for i in range(4)]

    def get_all_rotations(poly):
        rotations = [poly]
        for _ in range(3):
            new_rot = rotate(rotations[-1])
            rotations.append(new_rot)
        return rotations

    def can_place(grid, poly, start_row, start_col):
        for r in range(4):
            for c in range(4):
                if poly[r][c] == '#':
                    nr, nc = start_row + r, start_col + c
                    if nr < 0 or nr >= 4 or nc < 0 or nc >= 4 or (grid[nr][nc] == '#'):
                        return False
        return True

    def place_poly(grid, poly, start_row, start_col, char):
        new_grid = [list(row) for row in grid]
        for r in range(4):
            for c in range(4):
                if poly[r][c] == '#':
                    new_grid[start_row + r][start_col + c] = char
        return [''.join(row) for row in new_grid]

    def backtrack(grid, index):
        if index == 3:
            return all(cell == '#' for row in grid for cell in row)

        for rotation in get_all_rotations(polyominoes[index]):
            for r in range(4):
                for c in range(4):
                    if can_place(grid, rotation, r, c):
                        new_grid = place_poly(grid, rotation, r, c, '#')
                        if backtrack(new_grid, index + 1):
                            return True
        return False

    empty_grid = ['.' * 4 for _ in range(4)]
    if backtrack(empty_grid, 0):
        print("Yes")
    else:
        print("No")

fill_polyominoes()
```

