def count_infection_sequences(n, sick):
    MOD = 10**9 + 7

    # Find gaps between infected children
    gaps = []
    if sick[0] > 0:
        gaps.append(sick[0])
    for i in range(1, len(sick)):
        gaps.append(sick[i] - sick[i - 1] - 1)
    if sick[-1] < n - 1:
        gaps.append(n - 1 - sick[-1])

    # Calculate the number of ways to infect children in the gaps
    total_ways = 1
    for gap in gaps:
        if gap > 0:
            total_ways = total_ways * (gap + 1) % MOD

    # Calculate the total number of ways considering the order of infection
    result = total_ways
    for i in range(1, len(gaps) + 1):
        result = result * i % MOD

    return result
