def count_right_triangles(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Create a list to count 1s in each row and column
    row_count = [0] * rows
    col_count = [0] * cols

    # Fill row_count and col_count
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                row_count[r] += 1
                col_count[c] += 1

    triangle_count = 0

    # Count right triangles
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                # Right triangle: 1 in the same row (r), and 1 in the same column (c)
                # The third point will be (r', c) where r' != r
                # Need at least 2 other ones in the row and 2 in the column
                if row_count[r] > 1 and col_count[c] > 1:
                    triangle_count += (row_count[r] - 1) * (col_count[c] - 1)

    return triangle_count
