def product_matrix(grid):
    MOD = 12345
    n = len(grid)
    m = len(grid[0])

    total_product = 1
    zero_count = 0

    # Calculate the total product and count zeros
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 0:
                zero_count += 1
            else:
                total_product *= grid[i][j]
                total_product %= MOD

    # Create the product matrix
    p = [[0] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if zero_count > 1:
                p[i][j] = 0
            elif zero_count == 1:
                # If there is one zero, the result for any element not at zero position is 0
                if grid[i][j] == 0:
                    p[i][j] = total_product
                else:
                    p[i][j] = 0
            else:
                # If no zeros, calculate the product for the position
                p[i][j] = (total_product * pow(grid[i][j], MOD - 2, MOD)) % MOD

    return p
```

