def minimum_length_after_join(words):
    n = len(words)
    if n == 1:
        return len(words[0])

    # Initialize the list to store the minimum lengths
    dp = [[0] * n for _ in range(n)]

    # Fill the dp list with the join lengths
    for i in range(n):
        dp[i][i] = len(words[i])

    for length in range(2, n + 1):  # length of the segment
        for i in range(n - length + 1):
            j = i + length - 1
            # We can join words[i] and words[j], or we can take the intermediate results
            dp[i][j] = min(
                dp[i][j-1] + len(words[j]) - (1 if words[j-1][-1] == words[j][0] else 0),
                dp[i+1][j] + len(words[i]) - (1 if words[i][-1] == words[i+1][0] else 0)
            )

    return dp[0][n-1]
