def countWays(k):
    mod = 10**9 + 7
    dp = {}

    def helper(pos, jump):
        if pos < 0:
            return 0
        if (pos, jump) in dp:
            return dp[(pos, jump)]

        ways = 0

        if pos == k:
            ways += 1

        # Move down to i - 1, can only do if not consecutive
        if pos > 0:
            ways += helper(pos - 1, 0)  # reset jump to 0 because we move down

        # Move up to i + 2^jump
        new_pos = pos + (1 << jump)  # 2^jump
        ways += helper(new_pos, jump + 1)

        dp[(pos, jump)] = ways % mod
        return dp[(pos, jump)]

    return helper(1, 0)
```

