        # Count frequencies of the first half substring s[a:b+1]
        for char in s[a:b + 1]:
            if char in left_count:
                left_count[char] += 1
            else:
                left_count[char] = 1

        # Count frequencies of the second half substring s[c:d+1]
        for char in s[c:d + 1]:
            if char in right_count:
                right_count[char] += 1
            else:
                right_count[char] = 1

        # Combine both counts to check for palindrome conditions
        total_count = left_count.copy()

        for char, count in right_count.items():
            if char in total_count:
                total_count[char] += count
            else:
                total_count[char] = count

        # Check if we can form a palindrome
        odd_count = sum(1 for count in total_count.values() if count % 2 != 0)

        # A string can form a palindrome if at most one character has an odd count
        answer.append(odd_count <= 1)

    return answer
