def minimum_string(a: str, b: str, c: str) -> str:
    from itertools import permutations

    def merge_strings(s1: str, s2: str) -> str:
        max_overlap = 0
        for i in range(1, min(len(s1), len(s2)) + 1):
            if s1[-i:] == s2[:i]:
                max_overlap = i
        return s1 + s2[max_overlap:]

    def get_combined_string(s1: str, s2: str, s3: str) -> str:
        merged = merge_strings(merge_strings(s1, s2), s3)
        return merged

    min_length = float('inf')
    result = None

    for perm in permutations([a, b, c]):
        combined = get_combined_string(perm[0], perm[1], perm[2])
        if len(combined) < min_length:
            min_length = len(combined)
            result = combined
        elif len(combined) == min_length and combined < result:
            result = combined

    return result
