def min_operations_to_median(nums, k):
    nums.sort()
    n = len(nums)
    median_index = (n - 1) // 2

    if nums[median_index] == k:
        return 0

    operations = 0

    if nums[median_index] < k:
        for i in range(median_index, n):
            if nums[i] < k:
                operations += k - nums[i]
            else:
                break
    else:
        for i in range(median_index, -1, -1):
            if nums[i] > k:
                operations += nums[i] - k
            else:
                break

    return operations
