def count_stable_arrays(zero: int, one: int, limit: int) -> int:
    MOD = 10**9 + 7

    # We're considering dp arrays for both '0's and '1's counts as 
    # valid arrays of a certain length that meets the conditions.
    dp = [[0] * (one + 1) for _ in range(zero + 1)]

    # Base case: there's one way to form a stable array with 0 '0's and 1 '1's.
    dp[0][1] = 1

    # Process each count of '0's and '1's to build up the number of ways.
    for z in range(zero + 1):
        for o in range(one + 1):
            if z > 0 and o > 0:
                # Check if we can add a '0' to the existing configurations.
                for length in range(1, limit + 1):
                    if z - length >= 0:
                        dp[z][o] = (dp[z][o] + dp[z - length][o]) % MOD

            if o > 1:
                # Check if we can add a '1' to the existing configurations.
                for length in range(1, limit + 1):
                    if o - length >= 0:
                        dp[z][o] = (dp[z][o] + dp[z][o - length]) % MOD

    return dp[zero][one]
