def maximum_complete_subset_sum(nums):
    from collections import defaultdict
    from math import gcd
    from functools import reduce

    def prime_factors(n):
        factors = defaultdict(int)
        d = 2
        while d * d <= n:
            while (n % d) == 0:
                factors[d] += 1
                n //= d
            d += 1
        if n > 1:
            factors[n] += 1
        return factors

    def normalize_factors(factors):
        return tuple((p, exp % 2) for p, exp in sorted(factors.items()) if exp % 2 != 0)

    factor_map = defaultdict(list)

    for num in nums:
        factors = prime_factors(num)
        norm_factors = normalize_factors(factors)
        factor_map[norm_factors].append(num)

    max_sum = 0
    for values in factor_map.values():
        max_sum = max(max_sum, sum(values))

    return max_sum
