def punishment_number(n: int) -> int:
    def can_partition(num_str: str, target: int) -> bool:
        length = len(num_str)
        dp = [False] * (target + 1)
        dp[0] = True  # Sum of 0 is always possible

        for start in range(length):
            for end in range(start + 1, length + 1):
                part = int(num_str[start:end])
                if part > target:
                    continue
                for t in range(target, part - 1, -1):
                    dp[t] = dp[t] or dp[t - part]

        return dp[target]

    punishment_sum = 0

    for i in range(1, n + 1):
        square = i * i
        if can_partition(str(square), i):
            punishment_sum += square

    return punishment_sum
