def min_cost_to_convert(source, target, original, changed, cost):
    from collections import defaultdict
    import sys

    n = len(source)

    # When source and target are the same
    if source == target:
        return 0

    # Map to store the cost of changing each character
    change_map = defaultdict(list)

    for i in range(len(original)):
        change_map[original[i]].append((changed[i], cost[i]))

    total_cost = 0

    # Dictionary to count necessary changes
    need_changes = defaultdict(int)

    for i in range(n):
        if source[i] != target[i]:
            need_changes[source[i]] += 1

    for x, count in need_changes.items():
        if x not in change_map:
            return -1

        min_cost = sys.maxsize

        for y, c in change_map[x]:
            if y in need_changes:
                # Calculate the cost for this character change
                total_cost += count * c
                min_cost = min(min_cost, c)

        if min_cost == sys.maxsize:
            return -1

    return total_cost
