def max_sum_almost_unique_subarray(nums, m, k):
    n = len(nums)
    if k > n:
        return 0

    max_sum = 0
    current_sum = sum(nums[:k])
    count_map = {}

    for i in range(k):
        count_map[nums[i]] = count_map.get(nums[i], 0) + 1

    if len(count_map) >= m:
        max_sum = current_sum

    for i in range(k, n):
        current_sum += nums[i] - nums[i - k]
        count_map[nums[i]] = count_map.get(nums[i], 0) + 1
        count_map[nums[i - k]] -= 1

