from collections import defaultdict, deque

def canTraverseAllPairs(nums):
    n = len(nums)
    if n < 2:
        return True

    # Create a graph where an edge exists if gcd(nums[i], nums[j]) > 1
    graph = defaultdict(list)

    # Build the graph
    for i in range(n):
        for j in range(i + 1, n):
            if gcd(nums[i], nums[j]) > 1:
                graph[i].append(j)
                graph[j].append(i)

    # Perform BFS/DFS to check connectivity
    visited = [False] * n

    def bfs(start):
        queue = deque([start])
        visited[start] = True
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    # Start BFS from the first index
    bfs(0)

    # Check if all indices were visited
    return all(visited)
