def smallest_lexicographic_array(nums, limit):
    from collections import defaultdict, deque

    n = len(nums)
    graph = defaultdict(list)

    # Build a graph where edges connect nodes i and j if |nums[i] - nums[j]| <= limit
    for i in range(n):
        for j in range(i + 1, n):
            if abs(nums[i] - nums[j]) <= limit:
                graph[i].append(j)
                graph[j].append(i)

    visited = [False] * n
    result = nums[:]

    # Function to perform DFS and collect all connected components
    def dfs(node, component):
        stack = [node]
        while stack:
            curr = stack.pop()
            if not visited[curr]:
                visited[curr] = True
                component.append(curr)
                for neighbor in graph[curr]:
                    if not visited[neighbor]:
                        stack.append(neighbor)

    # Find connected components and sort them
    for i in range(n):
        if not visited[i]:
            component = []
            dfs(i, component)
            # Extract the values corresponding to the indices in the component
            values = [nums[index] for index in component]
            values.sort()
            component.sort()
            # Assign the sorted values back to the result at the correct indices
            for idx, val in zip(component, values):
                result[idx] = val

    return result
```

