def maxGroups(usageLimits):
    usageLimits.sort(reverse=True)
    groups = 0
    current_group_size = 0
    available_usage = 0

    for limit in usageLimits:
        available_usage += limit

    while available_usage > 0:
        current_group_size += 1
        if available_usage < current_group_size:
            break

        for i in range(len(usageLimits)):
            if usageLimits[i] > 0 and current_group_size > 0:
                usageLimits[i] -= 1
                available_usage -= 1
                current_group_size -= 1

        if current_group_size == 0:
            groups += 1
            current_group_size = groups + 1

    return groups
