def specialPerm(nums):
    from itertools import permutations

    MOD = 10**9 + 7
    count = 0

    def is_special_permutation(perm):
        for i in range(len(perm) - 1):
            if perm[i] % perm[i + 1] != 0 and perm[i + 1] % perm[i] != 0:
                return False
        return True

    for perm in permutations(nums):
        if is_special_permutation(perm):
            count += 1

    return count % MOD
