```python
def minCostToMakeEqual(s1: str, s2: str, x: int) -> int:
    n = len(s1)
    cost = 0
    diff = 0

    for i in range(n):
        if s1[i] != s2[i]:
            diff += 1

    if diff % 2 != 0:
        return -1

    # Count pairs of differences
    ones_needed = 0
    zeros_needed = 0

    for i in range(n - 1):
        if s1[i] != s2[i]:
            if s1[i] == '1':
                ones_needed += 1
            else:
                zeros_needed += 1

            # Check for the next bit as well
            if s1[i + 1] != s2[i + 1]:
                if s1[i + 1] == '1':
                    ones_needed += 1
                else:
                    zeros_needed += 1

                # Use the second operation for consecutive differences
                cost += 1
                s1 = s1[:i] + s1[i + 1:i + 2] + s1[i] + s1[i + 2:]

    # To resolve the remaining discrepancies using the first operation
    total_flips = max(ones_needed, zeros_needed)

    # Calculate the cost based on pairs and extra differences
    cost += (total_flips // 2) * x
    if total_flips % 2 == 1:
        cost += x

    return cost
```

