def longest_good_subarray(nums, k):
    left = 0
    freq = {}
    longest = 0

    for right in range(len(nums)):
        if nums[right] in freq:
            freq[nums[right]] += 1
        else:
            freq[nums[right]] = 1

        while freq[nums[right]] > k:
            freq[nums[left]] -= 1
            if freq[nums[left]] == 0:
                del freq[nums[left]]
            left += 1

        longest = max(longest, right - left + 1)

    return longest
